css:
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.tile {
  display: grid;
  place-items: center;
  height: 120px;
  border-radius: 10px;
  background-image: linear-gradient(135deg, #f97316, #db2777, #7c3aed);
  color: #ffffff;
  font-weight: 600;
  cursor: pointer;
}

.grey {
  filter: grayscale(1);
}

.blurry {
  filter: blur(3px);
}

.dim {
  filter: brightness(0.5);
}

.lifted {
  filter: drop-shadow(0 8px 8px rgb(0 0 0 / 0.35));
}

.tile:hover {
  filter: none;
}
